  1050      u8 *old_pos = ctx->pos;
  1051
  1052      /* Decode the DataType */
  1053      UA_NodeId typeId;
  1054      UA_NodeId_init(&typeId);
  1055      status ret = DECODE_DIRECT(&typeId, NodeId);
  1056      if(ret != UA_STATUSCODE_GOOD)
  1057          return ret;
  1058
  1059      /* Decode the EncodingByte */
  1060      u8 encoding;
  1061      ret = DECODE_DIRECT(&encoding, Byte);
  1062      if(ret != UA_STATUSCODE_GOOD) {
  1063          UA_NodeId_deleteMembers(&typeId);
  1064          return ret;
  1065      }
  1066
  1067      /* Search for the datatype. Default to ExtensionObject. */
  1068      if(encoding == UA_EXTENSIONOBJECT_ENCODED_BYTESTRING &&
  1069         (dst->type = UA_findDataTypeByBinaryInternal(&typeId, ctx)) != NULL) {
  1070          /* Jump over the length field (TODO: check if length matches) */
  1071          ctx->pos += 4;
  1072      } else {
  1073          /* Reset and decode as ExtensionObject */
  1074          dst->type = &UA_TYPES[UA_TYPES_EXTENSIONOBJECT];
  1075          ctx->pos = old_pos;
  1076          UA_NodeId_deleteMembers(&typeId);
  1077      }
